import type { Image } from './image'

// list of image file extensions comes from the user_image.do form
type ImageExtension = 'jpg' | 'png' | 'bmp' | 'gif' | 'jpeg' | 'ico' | 'svg'
type ImagePath = `${string}.${ImageExtension | Uppercase<ImageExtension>}`

declare global {
    namespace Now {
        function attach(path: ImagePath): Image
    }
}
